const crypto = require('crypto');
const secret = $env.ACTION_WEBHOOK_SECRET;
if (!secret) throw new Error('ACTION_WEBHOOK_SECRET is not configured');
const signature = $json.headers?.['x-autosfera-signature'] || '';
const raw = typeof $json.body === 'string' ? $json.body : JSON.stringify($json.body);
const expected = crypto.createHmac('sha256', secret).update(raw).digest('hex');
if (signature.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected))) throw new Error('Invalid Action Gateway signature');
const job = typeof $json.body === 'string' ? JSON.parse($json.body) : $json.body;
const allowed = {create_lead: 'lead', create_test_drive: 'test_drive', create_service: 'service'};
if (!Object.prototype.hasOwnProperty.call(allowed, job.action_type)) throw new Error('Unsupported action_type');
if (job.kind !== allowed[job.action_type]) throw new Error('action_type_kind_mismatch');
const issuedAt = Number(job.issued_at);
if (!Number.isFinite(issuedAt) || Math.abs((Date.now() / 1000) - issuedAt) > 300) throw new Error('stale_or_invalid_timestamp');
if (!job.nonce || String(job.nonce).length < 8) throw new Error('nonce_required');
if (!job.idempotency_key || !job.trace_id || !job.dealer_id || !job.action_id) throw new Error('missing_correlation');
if (!job.payload || typeof job.payload !== 'object') throw new Error('invalid_payload');
return [{json: job}];

const adapters = {create_lead: {workflow: 'AUTOSFERA_WF-10_SALES_LEAD', kind: 'lead'}, create_test_drive: {workflow: 'AUTOSFERA_WF-11_TEST_DRIVE', kind: 'test_drive'}, create_service: {workflow: 'AUTOSFERA_WF-20_SERVICE_BOOKING', kind: 'service'}};
const spec = adapters[$json.action_type];
if (!spec) throw new Error('Unsupported action_type');
return [{json: {...$json, result: {provider: 'n8n-sandbox', workflow: spec.workflow, action_type: $json.action_type, kind: spec.kind, external_id: $execution.id}}}];

const crypto = require('crypto');
const callback = {action_id: $json.action_id, dealer_id: $json.dealer_id, trace_id: $json.trace_id, status: 'completed', result: $json.result};
const raw = JSON.stringify(callback);
const signature = crypto.createHmac('sha256', $env.ACTION_WEBHOOK_SECRET).update(raw).digest('hex');
return [{json: {raw, signature}}];
